sections.code:
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "logs" {
  bucket = "opsdeck-demo-logs-123456789012"

  tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true

  tags = {
    Name = "opsdeck-dev"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "${aws_vpc.main.tags["Name"]}-public"
  }
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.al2023.id
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public.id

  root_block_device {
    volume_size = 8
    encrypted   = true
  }

  tags = {
    Name = "opsdeck-web"
  }
}

variable "environment" {
  description = "Deployment environment"
  type        = string

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be dev, staging or prod."
  }
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
}

variable "allowed_cidrs" {
  type    = list(string)
  default = ["10.0.0.0/8"]
}

variable "extra_tags" {
  type    = map(string)
  default = {}
}

variable "volume" {
  type = object({
    size_gb   = number
    encrypted = optional(bool, true)
  })
  default = { size_gb = 8 }
}

variable "db_password" {
  type      = string
  sensitive = true
}

# dev.tfvars
environment   = "dev"
instance_type = "t3.micro"
volume        = { size_gb = 8 }
extra_tags    = { Team = "platform" }

# locals.tf
locals {
  name_prefix = "opsdeck-${var.environment}"
  common_tags = merge(var.extra_tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
  })
}

# outputs.tf
output "instance_public_ip" {
  description = "Public IP of the web server"
  value       = aws_instance.web.public_ip
}

output "vpc_id" {
  value = aws_vpc.main.id
}

variable "bucket_names" {
  type    = set(string)
  default = ["logs", "backups", "uploads"]
}

resource "aws_s3_bucket" "app" {
  for_each = var.bucket_names
  bucket   = "opsdeck-${var.environment}-${each.key}-123456789012"

  tags = local.common_tags
}

resource "aws_s3_bucket" "audit" {
  count  = var.environment == "prod" ? 1 : 0
  bucket = "opsdeck-prod-audit-123456789012"
}

variable "ingress_ports" {
  type    = list(number)
  default = [80, 443]
}

resource "aws_security_group" "web" {
  name   = "${local.name_prefix}-web"
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.ingress_ports
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

locals {
  port_names = { for p in var.ingress_ports : tostring(p) => "port-${p}" }
}

terraform {
  backend "s3" {
    bucket       = "opsdeck-tfstate-123456789012"
    key          = "dev/network/terraform.tfstate"
    region       = "us-east-1"
    encrypt      = true
    use_lockfile = true
  }
}

terraform {
  required_version = ">= 1.6.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = { ManagedBy = "terraform" }
  }
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "dr" {
  provider = aws.west
  bucket   = "opsdeck-dr-${random_id.suffix.hex}"
}

# This file is maintained automatically by "terraform init".
# Manual edits may be lost in future updates.

provider "registry.terraform.io/hashicorp/aws" {
  version     = "5.72.1"
  constraints = "~> 5.0"
  hashes = [
    "h1:Yk3n9qZ0Tn0xk2c7QJd8rG1hX5mY0uWnq1b0m9eZc0M=",
    "zh:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
  ]
}

resource "aws_s3_bucket" "data" {
  bucket = "opsdeck-prod-data-123456789012"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.al2023.id
  instance_type = "t3.small"

  lifecycle {
    create_before_destroy = true
    ignore_changes        = [tags["LastPatched"]]
  }
}
